L,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null,\"scope\":null}','2022-02-12 07:22:59','2022-03-14 19:07:47'),(10,'ask_questions','ask-questions','Задать вопрос','Задать вопрос','voyager-window-list','App\\Models\\AskQuestion',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null,\"scope\":null}','2022-02-12 07:33:51','2022-02-12 08:07:41'),(11,'page_metas','page-metas','Метаданные страниц','Метаданные страниц','voyager-pen','App\\Models\\PageMeta',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null,\"scope\":null}','2022-02-12 09:20:58','2022-02-12 09:25:43'),(12,'faq','faq','Блоки FAQ','Блоки FAQ','voyager-puzzle','App\\Models\\Faq',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null}','2022-02-12 09:33:14','2022-02-12 09:33:14'),(13,'faq_blocks','faq-blocks','Блоки FAQ','Блоки FAQ','voyager-puzzle','App\\Models\\FaqBlock',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null,\"scope\":null}','2022-02-12 10:05:12','2022-02-12 10:07:12'),(14,'place_blocks','place-blocks','Блоки местонахождение','Блоки местонахождение','voyager-puzzle','App\\Models\\PlaceBlock',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null,\"scope\":null}','2022-02-26 08:28:52','2022-02-27 09:16:47'),(15,'employees','employees','Команда','Команда','voyager-people','App\\Models\\Employee',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null,\"scope\":null}','2022-02-26 09:45:20','2022-03-23 18:17:25'),(16,'team_blocks','team-blocks','Блоки команда','Блоки команда','voyager-puzzle','App\\Models\\TeamBlock',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null}','2022-02-26 10:15:37','2022-02-26 10:15:37'),(17,'about_blocks','about-blocks','Блоки о лагере','Блоки о лагере','voyager-puzzle','App\\Models\\AboutBlock',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null}','2022-02-26 11:58:33','2022-02-26 11:58:33'),(18,'features','features','Особенности','Особенности','voyager-star','App\\Models\\Feature',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null,\"scope\":null}','2022-02-27 08:56:19','2022-03-23 18:29:43'),(19,'skills','skills','Навыки','Навыки','voyager-receipt','App\\Models\\Skill',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null,\"scope\":null}','2022-02-27 11:42:27','2022-03-23 18:41:01'),(20,'programs','programs','Программы','Программы','voyager-book','App\\Models\\Program',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null,\"scope\":null}','2022-02-27 11:44:02','2022-03-23 18:41:26'),(21,'shifts','shifts','Смены','Смены','voyager-bell','App\\Models\\Shift',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null,\"scope\":null}','2022-02-27 11:57:11','2022-02-27 11:59:42'),(22,'shift_periods','shift-periods','Периоды смен','Периоды смен','voyager-calendar','App\\Models\\ShiftPeriod',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null,\"scope\":null}','2022-03-12 12:59:04','2022-03-12 14:46:38'),(23,'shift_programs','shift-programs','Программы смен','Программы смен','voyager-tag','App\\Models\\ShiftProgram',NULL,NULL,NULL,1,0,'{\"order_column\":null,\"order_display_column\":null,\"order_direction\":\"asc\",\"default_search_key\":null}','2022-03-12 14:40:41','2022-03-12 14:40:41');
