LOCK TABLES `employees` WRITE;
/*!40000 ALTER TABLE `employees` DISABLE KEYS */;
INSERT INTO `employees` VALUES (1,'Даша Свищева','Методист','<p>Бакалавр в области международных отношений, переводчик, преподаватель английского, французского и арабского языков, в настоящее время получает третье педагогическое образование. Увлекается лингвистикой, хореографией, научно- популярной литературой, обожает детей.</p>','2022-02-19 07:57:59','2022-02-19 07:57:59','employees/February2022/CqR3oNkE59625nmBX7Dh.png'),(2,'Полина Салита','Вожатая','<p>Студентка Института филологии МПГУ, будущий учитель русского языка и литературы. 9 лет занималась плаванием. Каждое лето проводила в детском лагере. С тех пор ничего не изменилось, только теперь в лагере в качестве вожатого и преподавателя русского языка, как иностранного.</p>','2022-02-19 07:58:30','2022-02-19 11:44:35','employees/February2022/pJ5H6lCwAiQGMyXro6Yg.png'),(3,'Антон Носов','Методист','<p>Дипломированный социолог, специализация по организации работы с молодежью. Футболист в душе и спортивный журналист. Опыт работы вожатым &ndash; 10 лет.</p>','2022-02-19 07:59:04','2022-02-19 11:45:00','employees/February2022/GCS1hNiwtQDAl2dOm9XT.png'),(4,'Тестовый персонаж 1','Тест','<p>Лорем ипсум 1</p>','2022-02-19 07:59:33','2022-02-19 07:59:33','employees/February2022/CHfkY0nzoSnXZoKwxUzV.jpg'),(5,'Тестовый персонаж 2','Тест','<p>Лорем ипсум 2</p>','2022-02-19 07:59:56','2022-02-19 07:59:56','employees/February2022/0pgP6uS52spjKhbuRSOa.jpg'),(6,'Тестовый персонаж 3','Тест','<p>Лорем ипсум 3</p>','2022-02-19 08:00:13','2022-02-19 08:00:13','employees/February2022/DNHJhb28GfSzO0TA3lVa.jpg'),(7,'Юлия Булдыкова','Маркетинг и реклама','<p>Бренд-менеджер JACOBS MONARCH, Mondelez International Group (Kraft Foods RUS)</p>','2022-02-19 11:56:55','2022-02-19 11:56:55','employees/February2022/J8NsvHv3czV6I6qu0SL1.png'),(8,'Григорий Иванец','Актерское мастерство и кинорежесура','<p>Режиссер кинокомпании &laquo;Titan Cinema Production&raquo; (TCP)</p>','2022-02-19 11:57:52','2022-02-19 11:57:52','employees/February2022/zaG1Lh0fukz6oB3RUESZ.png'),(9,'Артем Тихонов','Авторский курс по целеполаганию','<p>Опытный психолог с 15-ти летним педагогическим стажем работы, разработчик ряда авторских программ и методик в сфере эффективного развития личности, автор книги &laquo;Путь лидера&raquo;</p>','2022-02-19 11:58:38','2022-02-19 11:58:38','employees/February2022/CpQQ2kRSsUo9oGsOjRHf.png'),(10,'Евгения Корнилова','Директор лагеря','<p>Стаж работы в области молодежной политики &mdash; 17 лет. Награждена Министерством образования РФ за большой вклад в воспитание молодежи. Автор лагеря учебы творческого актива под Калугой, который в 2014 году отпраздновал свое 20-летие. Последние несколько лет посвятила бизнесу.</p>','2022-02-19 11:59:16','2022-02-19 11:59:16','employees/February2022/G9aWsdr5FjLoltEacZJ0.png'),(11,'Александр Новиков','Бизнес-эксперт','<p>Операционный директор в TalkBank, активный участник бизнес сообщества, эксперт, бизнес-тренер, постоянный участник тематических конференций. Начинал свою деятельность в комитете по делам молодежи городской управы, где получил несколько государственных грантов на развитие программ для молодежи. Является автором ряда тренингов по целеполаганию, коммуникативным навыкам и самопрезентации.</p>','2022-02-19 11:59:42','2022-02-19 11:59:42','employees/February2022/DoGtUmznvKDWI7KWsHWW.png'),(13,'Ольга Суркова','Маркетолог проекта','<p>В свои 27 лет попробовала себя в области энергетики, телекоммуникаций, маркетинга и шоу- бизнеса. И всегда добивалась наивысших результатов. Находясь в постоянном поиске пришла к мысли, что уже может многим поделиться с другими. Ответственная, целеустремленная и всесторонне развита в творчестве. Является маркетологом и двигателем проекта.</p>','2022-02-19 12:00:44','2022-03-31 07:37:11','employees/March2022/WXSMwMtZJmQp5e68CzGR.jpg');
/*!40000 ALTER TABLE `employees` ENABLE KEYS */;
UNLOCK TABLES;

