/*!40000 ALTER TABLE `main_blocks` DISABLE KEYS */;
INSERT INTO `main_blocks` VALUES (1,'Лагерь, в который хочется возвращаться снова и снова',NULL,'<p style=\"box-sizing: inherit; margin: 0px 0px 1.5rem; padding: 0px; font-size: 16px; line-height: 1.5; text-rendering: optimizelegibility; font-family: Nunito, arial, sans-serif;\"><strong>Комок</strong> ― это молодежный лагерь с уникальной атмосферой, в которой каждый чувствует себя комфортно.</p>\r\n<p style=\"box-sizing: inherit; margin: 0px 0px 1.5rem; padding: 0px; font-size: 16px; line-height: 1.5; text-rendering: optimizelegibility; font-family: Nunito, arial, sans-serif;\">Новые друзья, миллион полезных навыков, вагон положительных эмоций и фотографий &mdash; вот что получит Ваш ребенок после посещения &laquo;Комка&raquo;</p>\r\n<p style=\"box-sizing: inherit; margin: 0px 0px 1.5rem; padding: 0px; font-size: 16px; line-height: 1.5; text-rendering: optimizelegibility; font-family: Nunito, arial, sans-serif;\">Мы поможем ребенку поверить в то, что перед ним открыты все двери, что он талантлив. Когда человек чувствует себя свободным и самодостаточным, он легко определяет для себя стиль, манеру, ценности, и задумывается о цели своей жизни. Помочь создать цель невозможно, но можно дать возможность понять её и сформулировать.&nbsp;</p>','Лагерь,','main-blocks/March2022/7hpSi6oZhvsWcgbMSlIN.jpg','2021-10-31 12:47:06','2022-04-10 10:54:13','Подробнее о сменах','/about'),(2,'Каждая смена неповторима',NULL,'<p><span style=\"font-family: Nunito, arial, sans-serif; font-size: 16px; text-align: center;\">Мы верим, что каждый ребенок талантлив и помогаем раскрыть свой потенциал, благодаря сменам с уникальными тематиками. </span></p>\r\n<p><span style=\"font-family: Nunito, arial, sans-serif; font-size: 16px; text-align: center;\">Неповторимая атмосфера позволяет реализовать самые простые и базовые потребности ребенка: быть понятым, принятым, \"своим\". В процессе подготовки мероприятий, постоянном взяимодействии со сверстниками рождается единый доброжелательный настрой.&nbsp;</span></p>','неповторима',NULL,'2021-10-31 12:47:33','2022-04-10 11:04:19',NULL,NULL),(3,'Смены для детей','7-12 лет','<p><span style=\"font-family: Nunito, arial, sans-serif; font-size: 16px;\">Развиваем навыки самопрезентации, ораторского мастерства и Soft skills, повышаем уровень общей эрудициии, самодисциплины, и все это в игровой, непринужденной форме.&nbsp;</span></p>','для детей','main-blocks/March2022/38VrZV9PinfhFYszPGaE.jpg','2021-10-31 12:48:02','2022-04-10 10:58:50','Выбрать смену','/shifts?age=younger'),(4,'Смены для подростков','13-17 лет','<p><span style=\"font-family: Nunito, arial, sans-serif; font-size: 16px;\">Обучающие и спортивные игры, психологические тренинги, направленные на гармонизацию отношений в мини-коллективе, целеполагание, развитие лидерских навыков (приоритизация, осознанность, умение взять ответственность), индивидуальные и групповые задания для раскрытия творческого потенциала.&nbsp;</span></p>','для подростков','main-blocks/March2022/UurD75sHqkFzEH7OsnJU.jpg','2021-10-31 12:48:30','2022-04-10 10:54:02','Выбрать смену','/shifts'),(5,NULL,NULL,'<p>Путевка в наш лагерь - это выгодная инвестиция в развитие Вашего ребенка! Мы учим отдыхать и дружить, верить в себя и стремиться к цели.</p>',NULL,NULL,'2021-10-31 12:49:22','2022-04-10 10:34:11',NULL,NULL),(6,'Больше, чем просто лагерь',NULL,'<p><span style=\"font-family: Nunito, arial, sans-serif; font-size: 16px;\">Уникальная атмосфера, талантливые вожатые и незабываемые эмоции &mdash; только часть причин, почему Ваш ребенок захочет возвращаться в Комок каждое лето. Но их так много, что нам пришлось сделать отдельную страницу, чтобы рассказать Вам о них.</span></p>','Больше,','main-blocks/March2022/HkFX3yGRnXbcMXyz9ARa.jpg','2021-10-31 12:49:51','2022-04-10 10:59:22','Узнать все о лагере','/about');
/*!40000 ALTER TABLE `main_blocks` ENABLE KEYS */;
UNLOCK TABLES;

