INSERT INTO `page_metas` VALUES (1,'gallery','Галерея','<p style=\"box-sizing: inherit; margin: 0px 0px 1.5rem; padding: 0px; font-size: 16px; line-height: 1.5; text-rendering: optimizelegibility; color: #000000; font-family: Nunito, arial, sans-serif;\">Наш любимый фотоальбом. Здесь вы можете познакомиться с жизнью нашего лагеря, или вспомнить о веселых и интересных деньках. Честно говоря, мы и сами частенько пересматриваем эти фотографии.</p>\r\n<p style=\"box-sizing: inherit; margin: 0px 0px 1.5rem; padding: 0px; font-size: 16px; line-height: 1.5; text-rendering: optimizelegibility; color: #000000; font-family: Nunito, arial, sans-serif;\">Укажите в каком году вы были в лагере и в какой смене. У нас все сохранено.</p>','2022-02-12 09:26:30','2022-02-12 09:26:30'),(2,'reviews','Отзывы','<p><span style=\"color: #000000; font-family: Nunito, arial, sans-serif; font-size: 16px;\">Давайте спросим у детей, что они думают о лагере.</span></p>','2022-02-12 09:27:01','2022-02-12 09:27:01'),(3,'faq','Вопросы и ответы','<p><span style=\"color: #000000; font-family: Nunito, arial, sans-serif; font-size: 16px;\">Мы подготовили для вас ответы на часто задаваемые вопросы от родителей и детей</span></p>','2022-02-12 09:27:33','2022-02-12 09:27:33'),(4,'team','Команда',NULL,'2022-02-23 21:21:14','2022-02-23 21:21:15'),(5,'place','Местонахождение',NULL,'2022-02-26 08:20:48','2022-02-26 08:20:48'),(6,'shifts','Смены для подростков',NULL,'2022-03-12 13:29:56','2022-03-12 13:30:53');
/*!40000 ALTER TABLE `page_metas` ENABLE KEYS */;
UNLOCK TABLES;

