INSERT INTO `place_blocks` VALUES (1,'Дом отдыха «Подмосковье»','<p><span style=\"color: #000000; font-family: Nunito, arial, sans-serif; font-size: 16px;\">Именно тут мы проводим наш лагерь и приглашаем ваших детей окунуться в атмосферу активного полезного отдыха, творчества и креативности. Скучать будет некогда!</span></p>','[\"place-blocks\\/February2022\\/eWkyLOiUDU7B9tnaQ2oy.png\",\"place-blocks\\/February2022\\/hYIQrRmKsUuij1xkkSQt.png\",\"place-blocks\\/February2022\\/4rcULEF72On3W1sbd7oO.png\"]','2022-02-26 09:39:10','2022-02-26 10:33:07','«Подмосковье»'),(2,'Лагерь на карте','<p><span style=\"color: #000000; font-family: Nunito, arial, sans-serif; font-size: 16px;\">Мытищинский район, с. Троицкое</span><br style=\"box-sizing: inherit; color: #000000; font-family: Nunito, arial, sans-serif; font-size: 16px;\" /><span style=\"color: #000000; font-family: Nunito, arial, sans-serif; font-size: 16px;\">В 12 км от Москвы</span></p>',NULL,'2022-02-26 10:33:42','2022-02-26 10:33:42','на карте'),(3,'Примите участие в ознакомительной поездке','<p>Сомневаетесь, соответствуют ли условия проживания вашим ожиданиям? Мы предоставляем вам возможность своими глазами увидеть номера, оснащение и территорию лагеря. Выезды организуются по предварительной записи. Просто заполните заявку и мы подберем для вас подходящую дату. Все увидите сами!</p>',NULL,'2022-02-26 10:34:00','2022-02-26 11:07:54','в ознакомительной поездке');
/*!40000 ALTER TABLE `place_blocks` ENABLE KEYS */;
UNLOCK TABLES;

