/*!40000 ALTER TABLE `programs` DISABLE KEYS */;
INSERT INTO `programs` VALUES (1,'Комок kids','<h5 style=\"box-sizing: inherit; margin: 0px 0px 0.75rem; padding: 0px; font-family: Nunito, arial, sans-serif; color: #000000; text-rendering: optimizelegibility; font-size: 1.25rem; line-height: 22.8px;\">Юные лидеры России</h5>\r\n<p style=\"box-sizing: inherit; margin: 0px 0px 3.125rem; padding: 0px; font-size: 20px; line-height: 1.5; text-rendering: optimizelegibility; color: #000000; font-family: Nunito, arial, sans-serif;\">Начнем новую жизнь вместе? Разберемся, что такое правильное питание. Научимся правильно двигаться и дышать, подключим осознанность, самоконтроль. Когда нужно ложиться спать и как просыпаться вовремя? Как использовать трекеры сна, настроения и активностей. Био-хакинг &mdash; как заставить мозг работать эффективнее. Как преодолевать последствия негативных ситуаций и постичь науку стресс менеджмента (управление стрессами).</p>','2022-02-27 11:46:03','2022-03-24 07:00:59','[{\"download_link\":\"programs\\/March2022\\/1Y8CetgBc7NGZ4V9lX8S.svg\",\"original_name\":\"Frame.svg\"}]'),(2,'Курс «Живые системы»','<p><span style=\"color: #000000; font-family: Nunito, arial, sans-serif; font-size: 20px;\">На занятиях по &laquo;Биотехнологии&raquo; участники смены изучат клетки крови, а на Scrath-программировании обучатся визуальному программированию &ndash; освоят основы двух направлений и создадут уникальный проект &ndash; междисциплинарную 2D игру &laquo;Живые системы&raquo;, которая позволит поиграть за разные клетки человеческого тела: эритроциты, лейкоциты, тромбоциты.</span></p>','2022-02-27 11:46:19','2022-03-24 06:59:41','[{\"download_link\":\"programs\\/March2022\\/XkTFOgPeUe0A2bKT1hyG.svg\",\"original_name\":\"Frame-1.svg\"}]'),(3,'Школа молодого инженера','<h5 style=\"box-sizing: inherit; margin: 0px 0px 0.75rem; padding: 0px; font-family: Nunito, arial, sans-serif; color: #000000; text-rendering: optimizelegibility; font-size: 1.25rem; line-height: 22.8px;\">&laquo;Программирование&raquo; (2-я и 4-я смена)</h5>\r\n<p style=\"box-sizing: inherit; margin: 0px 0px 3.125rem; padding: 0px; font-size: 20px; line-height: 1.5; text-rendering: optimizelegibility; color: #000000; font-family: Nunito, arial, sans-serif;\">Изучим самые популярные языки С++, Python и др., создадим игру и разберемся в науке &laquo;Биотехнология&raquo;.</p>\r\n<h5 style=\"box-sizing: inherit; margin: 0px 0px 0.75rem; padding: 0px; font-family: Nunito, arial, sans-serif; color: #000000; text-rendering: optimizelegibility; font-size: 1.25rem; line-height: 22.8px;\">&laquo;Нейро и биотехнологии&raquo; (3-я смена)</h5>\r\n<p style=\"box-sizing: inherit; margin: 0px 0px 3.125rem; padding: 0px; font-size: 20px; line-height: 1.5; text-rendering: optimizelegibility; color: #000000; font-family: Nunito, arial, sans-serif;\">Изучение импульсов тела и датчиков, разберемся в молекулярной кухне и основах рац. питания.</p>\r\n<h5 style=\"box-sizing: inherit; margin: 0px 0px 0.75rem; padding: 0px; font-family: Nunito, arial, sans-serif; color: #000000; text-rendering: optimizelegibility; font-size: 1.25rem; line-height: 22.8px;\">&laquo;Гидравлика и пневматика&raquo; (4-я смена)</h5>\r\n<p style=\"box-sizing: inherit; margin: 0px 0px 3.125rem; padding: 0px; font-size: 20px; line-height: 1.5; text-rendering: optimizelegibility; color: #000000; font-family: Nunito, arial, sans-serif;\">Как работают приборы, где движущей силой является жидкость или воздух.</p>','2022-02-27 11:46:40','2022-03-24 06:59:32','[{\"download_link\":\"programs\\/March2022\\/G0e028BNLqbktnrNNKI0.svg\",\"original_name\":\"Frame-2.svg\"}]'),(4,'Перезагрузка','<p><span style=\"color: #000000; font-family: Nunito, arial, sans-serif; font-size: 20px;\">Начнем новую жизнь вместе? Разберемся, что такое правильное питание. Научимся правильно двигаться и дышать, подключим осознанность, самоконтроль. Когда нужно ложиться спать и как просыпаться вовремя? Как использовать трекеры сна, настроения и активностей. Био-хакинг &mdash; как заставить мозг работать эффективнее. Как преодолевать последствия негативных ситуаций и постичь науку стресс менеджмента (управление стрессами).</span></p>','2022-02-27 11:47:06','2022-03-24 06:59:25','[{\"download_link\":\"programs\\/March2022\\/xdE4lLIJrw4LROOLtDni.svg\",\"original_name\":\"Frame-3.svg\"}]'),(5,'Остаться в живых','<p><span style=\"color: #000000; font-family: Nunito, arial, sans-serif; font-size: 20px;\">Очень важно уметь самостоятельно обеспечить безопасность, будь то на время отъезда родителей или при переезде в другой город/страну по учебе. Курс для тех, кто готов начать независимую жизнь, разобраться с холодильником, ящиком для инструментов и домашней аптечкой. Научим основам выживания в любом большом городе 21 века в любой самой запутанной ситуации!</span></p>','2022-02-27 11:47:19','2022-03-24 06:59:14','[{\"download_link\":\"programs\\/March2022\\/Dog0WRci1f4vTh7SorzC.svg\",\"original_name\":\"Frame-4.svg\"}]'),(6,'Бизнес','<p><span style=\"color: #000000; font-family: Nunito, arial, sans-serif; font-size: 20px;\">Жизнь в лагере, как бизнес-модель. Вместе научимся зарабатывать и тратить, инвестировать и просчитывать риски. А разобраться нам помогут успешные бизнесмены и предприниматели, которые расскажут про деньги и финансовую грамотность без скучных лекций, но с реальными кейсами и захватывающими играми. Подготовься ко взрослой жизни уже сейчас!</span></p>','2022-02-27 11:47:30','2022-03-31 16:06:19','[{\"download_link\":\"programs\\/March2022\\/i8ywJrR56LQHfxZmJWXw.png\",\"original_name\":\"liar.png\"}]');
/*!40000 ALTER TABLE `programs` ENABLE KEYS */;
