INSERT INTO `shift_programs` VALUES (6,'Мир вокруг нас','<div style=\"text-align: left;\"><strong>Творческая тема - \"Мир вокруг нас\"</strong></div>\r\n<div style=\"text-align: left;\">Узнаем кто и почему зарегистрирован в красной книге, откроем&nbsp;тайны зыбучих песков, поймем, как работают вулканы. Заглянем в потаенные уголки нашей планеты, а также изучим самую необычную флору и фауну. Хочешь узнать нечто неожиданное о мире, который по привычке считаешь знакомым и обыденным? Тогда скорее пакуй свои вещи, мы ждем тебя!</div>\r\n<div style=\"text-align: left;\">&nbsp;</div>\r\n<div style=\"text-align: left;\"><strong>Напрвление курса: \"Туризм и Экология\"</strong></div>\r\n<div>\r\n<div style=\"text-align: left;\">Как жить в гармонии с природой? Как найти выход из гущи леса, собрать палатку, приготовить кашу на костре, пользоваться компасом? Как уметь правильно путешествовать и беречь красоту природы? Научимся собирать чемодан и планировать путешествия, уметь не заблудиться в лесу и в огромном мегаполисе. Узнаем о туристических традициях различных регионов родной страны и зарубежья, - тонкости внутреннего и внешнего туризма. И ещё множество вопросов, которые мы раскроем на курсе!</div>\r\n</div>','2022-04-10 12:32:26','2022-04-10 13:03:59'),(7,'Космоход','<div><strong>Курс от научной лаборатории \"Инжинириум МГТУ им. Н.Э.Баумана\" \"Космоход\" (для детей 10-16 лет</strong>)</div>\r\n<div>За 24 часа участники интенсива получат навыки по таким hard skills, как: 3D-моделирование, 3D-печать а также основы схемотехники. Каждый участник соберёт и унесёт с собой самоходного робота, который будет осуществлять движение вперёд при активации. Проект будет собран с применением современных технологий: Сначала ребята создадут трёхмерные модели деталей корпуса в ПО Autodesk Tinkercad, затем подготовят их к печати на 3D принтере, разберутся с принципиальной схемой подключения компонентом электрической цепи и соберут собственный проект.</div>\r\n<div>\r\n<div style=\"box-sizing: inherit; margin: 0px; padding: 0px; font-family: Nunito, arial, sans-serif; font-size: 16px;\">&nbsp;</div>\r\n<div style=\"box-sizing: inherit; margin: 0px; padding: 0px; font-family: Nunito, arial, sans-serif; font-size: 16px;\">Творческая тема - \"Мир вокруг нас\"</div>\r\n<div style=\"box-sizing: inherit; margin: 0px; padding: 0px; font-family: Nunito, arial, sans-serif; font-size: 16px;\">Узнаем кто и почему зарегистрирован в красной книге, откроем тайны зыбучих песков, поймем, как работают вулканы. Заглянем в потаенные уголки нашей планеты, а также изучим самую необычную флору и фауну. Хочешь узнать нечто неожиданное о мире, который по привычке считаешь знакомым и обыденным? Тогда скорее пакуй свои вещи, мы ждем тебя!</div>\r\n</div>','2022-04-10 12:39:01','2022-04-10 12:57:10'),(8,'SUPER - KIDS','<div style=\"color: #000000; font-family: \'ys text\', arial, sans-serif; font-size: 16px;\">\r\n<div><strong>Творческая тема - \"Super-kids\"</strong></div>\r\n<div>Тебе предстоит стать настоящим супергероем и отправиться в захватывающее путешествие по фантастическим мирам! От Marvel до DC, вместе с Бэтменом и Капитаном Америкой, по комиксам и киновселенным! Пакуй чемодан, ведь мы-то с тобой точно знаем, что \"бесконечность - не предел!\"</div>\r\n</div>\r\n<div style=\"color: #000000; font-family: \'ys text\', arial, sans-serif; font-size: 16px;\">&nbsp;</div>\r\n<div style=\"color: #000000; font-family: \'ys text\', arial, sans-serif; font-size: 16px;\"><strong>Направление курса - \"Театральное мастерство и Soft skills\"</strong></div>\r\n<div style=\"color: #000000; font-family: \'ys text\', arial, sans-serif; font-size: 16px;\">Придумаем сюжет посредством сторителлинга и снимем по нему фильм. Создадим костюмы с помощью ткани и иголки. Научимся делать грим, как лучшие визажисты. Освоим навыки актерского и ораторского мастерства. Научимся грамотно распределять свое время. А также попробуем разрекламировать свой фильм с помощью социальных сетей и наружной рекламы. Попробуем себя во всех ролях, и поймем, что по душе!</div>','2022-04-10 13:14:17','2022-04-10 13:35:28'),(9,'Шпионские игры','<p><strong>Творческая тема - \"Шпионские игры\"</strong></p>\r\n<p>Настоящий шпионаж - интереснейшее занятие, но не все так просто! Чтобы стать настоящим тайным агентов, тебе предствоит пройти обучение, создать команду, изучить протокол миссии, скрыть улики и усовершенствовать свою технику шпионада с помощью современных технологий! Трудно найти хорошего шпиона, но мы Тебя нашли! До встречи на самой загадочной смене лета 2022!&nbsp;</p>\r\n<p><strong>Направление курса - \"Проект театральная маска\"</strong></p>\r\n<div>Всегда мечтал прикоснуться к актерской жизни изнутри и сыграть на сцене театра, или же просто давно хотел избавиться от психологических блоков и неуверенности перед публикой? &nbsp;На смене мы освоим основы актерского мастерства, научимся играть и существовать на сцене, создадим декорации и костюмы. Мы погрузимся в прекрасный мир театра и фантазии, творчества и воображения.</div>','2022-04-10 13:40:16','2022-04-10 13:47:39'),(10,'1000 И ОДНО ПУТЕШЕСТВИЕ','<p>Что ты сделаешь, если в руки попадёт карта сокровищ потерянного в джунглях города, где все из золота? Или маршрут до таинственного острова обезьян? Уже пакуешь чемоданы? Не забудь спрей от комаров, мы отправляемся в кругосветное путешествие!</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Направление курса: \"Театральное мастерство и Soft Skills\" </strong></p>\r\n<p>Придумаем сюжет посредством сторителлинга и снимем по нему фильм. Создадим костюмы с помощью ткани и иголки. Научимся делать грим, как лучшие визажисты. Освоим навыки актерского и ораторского мастерства. Научимся грамотно распределять свое время. А также попробуем разрекламировать свой фильм с помощью социальных сетей и наружной рекламы. Попробуем себя во всех ролях, и поймем, что по душе!</p>\r\n<p>&nbsp;</p>\r\n<div>&nbsp;</div>','2022-04-10 14:36:47','2022-04-10 14:39:59'),(11,'Музыкальный калейдоскоп','<p>Любишь всё, что связано с музыкой? Постоянно смотришь клипы любимых исполнителей? Всегда мечтал написать или спеть песню? За одну смену в лагере ты смодешь попробовать себя в роли певца, музыкального продюсера, примеришь на себя образы великих артистов прошлого и новых звёзд, сыграешь свой первый концерт и снимешь первый клип.</p>\r\n<p><strong>Направление курса - \"Театральное мастерство и Soft skills\"</strong></p>\r\n<p>Придумаем сюжет посредством сторителлинга и снимем по нему фильм. Создадим костюмы при помощи ткани и иголки. Научимся делать грим, как лучшие визажисты. Освоим навыки актерского и ораторского мастерства. Научимся грамотно распределять свое время. А также попробуем разрекламировать свой фильм с помощью социальных сетей и наружной рекламы. Попробуем себя во всех ролях, и поймем, что по душе!</p>','2022-04-10 15:41:41','2022-04-10 15:47:08'),(12,'Эпоха джаза и немого кино - (20-30 годы XX века)','<p>Готов окунуться в эпоху \"Великого Гэтсби\"?! Давно мечтал сняться в немом кино? Интересно чем отличается блюз от кантри? Хочешь узнать, что было на пике моды в эти годы? Всего за две недели мы увидим, как изменился мир в 20-30-е и почему это время мафии.</p>\r\n<p><strong>Направление курса: \"Проект театральная маска\"</strong></p>\r\n<p>Всегда мечтал прикоснуться к актерской жизни изнутри и сыграть на сцене театра, или же просто давно хотел избавиться от психологических блоков и неуверенности перед публикой? На смене мы освоим основы актерского мастерства, научимся играть и существовать на сцене, создадим декорации и костюмы. Мы погрузимся в прекрасный мир театра и фантазии, творчества и воображения.&nbsp;</p>\r\n<p>&nbsp;</p>','2022-04-10 16:10:47','2022-04-10 16:10:47');
