INSERT INTO `team_blocks` VALUES (1,'Вашим ребенком будут заниматься наши молодые талантливые вожатые',NULL,'2022-02-19 10:38:00','2022-02-19 11:35:57','[\"1\", \"2\", \"3\", \"4\", \"6\"]','молодые талантливые вожатые'),(3,'Мастер-классы будут проводить профессионалы своего дела',NULL,'2022-02-19 12:01:27','2022-02-19 12:01:27','[\"4\", \"5\", \"7\", \"8\", \"9\"]','профессионалы своего дела'),(4,'Организаторы лагеря','<p><span style=\"color: #000000; font-family: Nunito, arial, sans-serif; font-size: 16px;\">&laquo;Видеть цель, верить в себя и не замечать препятствий!&raquo;</span></p>','2022-02-19 12:02:17','2022-03-31 16:00:42','[\"11\", \"13\"]','Организаторы');
